
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_sa_tpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_sa_tpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.717230218483552e+00, -4.621815601312321e+00, -4.488086626331070e+00, -4.302781424834327e+00, -4.050179500524313e+00, -3.713853643028425e+00, -3.281014473808622e+00, -2.751112710068585e+00, -2.150972844639821e+00, -1.553775346024968e+00, -1.035825245037119e+00, -6.942727649495134e-01, -6.016045025982575e-01, -5.112752164485550e-01, -3.663765482189741e-01, -2.311662098633643e-01, -1.346247986809400e-01, -6.406808331251772e-02, -2.770618977731825e-02, -1.311278562536544e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


